/**
 * Bundled qualification snapshot used by every visible tab.
 *
 * Functionality: loads the deterministic report generated by
 * `npm run benchmark:tabs` and freezes it through the suite contract.
 * Inputs: committed JSON qualification report.
 * Output: immutable suite plus tab lookup helpers.
 * Fallback: invalid report data fails the build rather than claiming status.
 */

import report from '../../reports/tab-benchmark-results.json';
import { createTabBenchmarkSuite, TAB_QUALIFICATION_STATUS } from './tabBenchmarkContracts.js';

export const tabBenchmarkSuite = createTabBenchmarkSuite(report);

const tabStatusLookup = Object.freeze(Object.fromEntries(
  tabBenchmarkSuite.tabs.map((tab) => [tab.tabId, tab.status]),
));

/**
 * Returns the qualification status for one visible tab.
 *
 * @param {string} tabId Registered tab identifier.
 * @returns {string} QUALIFIED, FAILED, or NOT_RUN.
 */
export function getTabQualificationStatus(tabId) {
  return tabStatusLookup[tabId] || TAB_QUALIFICATION_STATUS.NOT_RUN;
}
